cd /workspaces/semio && python3 -c "
import json
with open('semio/assets/semio/nakagin-capsule-tower.shallow.design.semio.json') as f:
    d = json.load(f)

# Understand naming convention:
# b = base
# ci = capital  
# t_fN = tambour floor N
# cs = capsule, sl = slot, d = direction
# br = bridge

# Group pieces by prefix
from collections import defaultdict
groups = defaultdict(list)
for p in d['pieces']:
    name = p['name']
    # Identify tower c0 vs c1
    if '_c0' in name:
        tower = 'c0'
    elif '_c1' in name:
        tower = 'c1'
    elif name == 'b':
        tower = 'shared'
    else:
        tower = 'unknown'

    # Identify piece kind
    if name.startswith('cs_'):
        kind = 'capsule'
    elif name.startswith('br_'):
        kind = 'bridge'
    elif name.startswith('t_'):
        kind = 'tambour'
    elif name.startswith('ci_'):
        kind = 'capital'
    elif name == 'b':
        kind = 'base'
    else:
        kind = 'other'

    groups[(tower, kind)].append(name)

for (tower, kind), names in sorted(groups.items()):
    print(f'{tower}/{kind}: {len(names)} pieces')
    for n in sorted(names)[:5]:
        print(f'  {n}')
    if len(names) > 5:
        print(f'  ... and {len(names)-5} more')
"

